@charset "UTF-8";
/**
 * CB Chat UI - 根变量定义
 *
 * 全局通用变量，不区分主题
 * 挂载到 :root，全局可用
 */
:root {
  /* ========== 字体系统 ========== */
  --cb-font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen', 'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  --cb-font-family-mono: 'Menlo', 'Monaco', 'Courier New', monospace;
  /* ========== 尺寸系统 ========== */
  --cb-spacing-xs: 4px;
  --cb-spacing-sm: 8px;
  --cb-spacing-md: 12px;
  --cb-spacing-lg: 16px;
  --cb-spacing-xl: 20px;
  --cb-spacing-xxl: 24px;
  /* ========== 圆角档位 ==========
     与 wb 设计稿 200/250/300 等档位对齐：sm=4 / md=6 / lg=8 / xl=16 / 2xl=24 */
  --cb-border-radius-sm: 4px;
  --cb-border-radius-md: 6px;
  --cb-border-radius-lg: 8px;
  --cb-border-radius-xl: 16px;
  --cb-border-radius-2xl: 24px;
  /* ========== 动画系统 ========== */
  --cb-transition-fast: 0.15s ease;
  --cb-transition-base: 0.2s ease;
  --cb-transition-slow: 0.3s ease;
  /* ========== Z-index 层级 ========== */
  --cb-z-index-dropdown: 100;
  --cb-z-index-modal: 1000;
  /* 确认对话框需要高于所有其他业务 modal（如 McpModal=10000、PreviewModal=10005/10006、
     conflict-modal=10020、cloud-file-panel=10010、top-progress-banner=100000）。
     业务侧不应再用更高的 z-index 盖住确认弹窗。 */
  --cb-z-index-modal-confirm: 100001;
  --cb-z-index-tooltip: 1100;
  /* ========== VSCode 主题变量映射 - 默认使用 Light 主题 ========== */
  /* 这样在没有 .light/.dark 类名时,默认显示为 Light 主题 */
  --cb-vscode-editor-background: var(--vscode-editor-background, #ffffff);
  --cb-vscode-sideBar-background: var(--vscode-sideBar-background, #f3f3f3);
  --cb-vscode-input-background: var(--vscode-input-background, #ffffff);
  --cb-vscode-dropdown-background: var(--vscode-dropdown-background, #ffffff);
  --cb-vscode-foreground: var(--vscode-foreground, #333333);
  --cb-vscode-editor-foreground: var(--vscode-editor-foreground, #4c4f69);
  --cb-vscode-titleBar-activeBackground: var(--vscode-titleBar-activeBackground, #dddddd);
  --cb-vscode-titleBar-activeForeground: var(--vscode-titleBar-activeForeground, #333333);
  --cb-vscode-titleBar-inactiveBackground: var(--vscode-titleBar-inactiveBackground, #dddddd);
  --cb-vscode-titleBar-inactiveForeground: var(--vscode-titleBar-inactiveForeground, #666666);
  --cb-titlebar-control-hover-background: rgba(0, 0, 0, 0.06);
  --cb-vscode-descriptionForeground: var(--vscode-descriptionForeground, #717171);
  --cb-vscode-widget-border: var(--vscode-widget-border, #e1e1e1);
  --cb-vscode-panel-border: var(--vscode-panel-border, #e1e1e1);
  --cb-vscode-list-hoverBackground: var(--vscode-list-hoverBackground, #f0f0f0);
  --cb-vscode-toolbar-hoverBackground: var(--vscode-toolbar-hoverBackground, #f0f0f0);
  --cb-vscode-button-background: var(--vscode-button-background, #007acc);
  --cb-vscode-button-foreground: var(--vscode-button-foreground, #ffffff);
  --cb-vscode-button-hoverBackground: var(--vscode-button-hoverBackground, #0062a3);
  --cb-vscode-scrollbarSlider-background: var(--vscode-scrollbarSlider-background, #c1c1c1);
  --cb-vscode-scrollbarSlider-hoverBackground: var(--vscode-scrollbarSlider-hoverBackground, #a8a8a8);
  --cb-vscode-textLink-foreground: var(--vscode-textLink-foreground, #006ab1);
  /* ========== 基础颜色系统 - Light 主题默认值 ========== */
  --cb-panel-bg-primary: var(--vscode-editor-background, #ffffff);
  --cb-text-primary: #333333;
  --cb-text-secondary: #666666;
  /* 灰阶禁用文本（credit-estimate / installed-plugins 等组件使用），
     light 与 wb 设计稿 --wb-color-text-disabled 对齐 */
  --cb-text-disabled: rgba(0, 0, 0, 0.30);
  --cb-text-link: #006ab1;
  --cb-stroke-secondary: #d8dee4;
  /* Markdown <hr> 边框色，与 wb 设计稿 --wb-color-border-secondary 对齐 */
  --cb-markdown-hr-border-color: #EBEBEB;
  --cb-bg-primary: rgba(0, 0, 0, 0.05);
  --cb-bg-secondary: #f5f5f5;
  --cb-team-member-card-background: #f5f5f5;
  --cb-team-member-icon-background: #F5F5F5;
  --cb-button-dark-background: #1a1a1a;
  --cb-button-dark-foreground: #ffffff;
  --cb-button-dark-hover-background: #333333;
  /* ========== 设计稿语义补齐（与 wb 设计稿一致；WorkBuddy 通过 cb-bridge.scss 桥接到 --wb-*） ==========
     这些 token 的设计意义来自 wb 设计稿，但 cb-chat-ui 必须自带 light/dark 默认值，
     避免 IDE 纯 cb 场景未注入 wb token 时回退到使用点的硬编码 fallback（可能在 dark 主题下导致黑底黑字）。 */
  --cb-text-error-active: #B42C3F;
  --cb-text-link-hover: #0E58A0;
  --cb-text-solid: #000000;
  --cb-bg-primary-hover: #EBEBEB;
  --cb-bg-primary-active: #F2F2F2;
  --cb-border-secondary: #EBEBEB;
  --cb-shadow-popover: 0 4px 12px -4px rgba(0, 0, 0, 0.04), 0 3px 6px -8px rgba(0, 0, 0, 0.04);
  --cb-border-drag-indicator: #1470B4;
  --cb-tooltip-bg: rgba(0, 0, 0, 0.70);
}
/**
 * CB Chat UI - Dark 主题变量
 *
 * 适用于：
 * 1. :root (默认主题)
 * 2. .dark / .cb-dark (全局类名)
 * 3. .cbChat.dark / .cbChat (组件类名)
 * 4. .cb-tooltip (独立组件)
 */
/* Dark 主题选择器 */
:root.dark,
:root.cb-dark,
:root .dark,
:root .cb-dark {
  /* ========== VSCode 主题变量映射 ========== */
  --cb-vscode-editor-background: var(--vscode-editor-background, #1e1e1e);
  --cb-vscode-sideBar-background: var(--vscode-sideBar-background, #252526);
  --cb-vscode-input-background: var(--vscode-input-background, #3c3c3c);
  --cb-vscode-dropdown-background: var(--vscode-dropdown-background, #3c3c3c);
  --cb-vscode-foreground: var(--vscode-foreground, #cccccc);
  --cb-vscode-editor-foreground: var(--vscode-editor-foreground, #cccccc);
  --cb-vscode-titleBar-activeBackground: var(--vscode-titleBar-activeBackground, #3c3c3c);
  --cb-vscode-titleBar-activeForeground: var(--vscode-titleBar-activeForeground, #cccccc);
  --cb-vscode-titleBar-inactiveBackground: var(--vscode-titleBar-inactiveBackground, #3c3c3c);
  --cb-vscode-titleBar-inactiveForeground: var(--vscode-titleBar-inactiveForeground, #999999);
  --cb-titlebar-control-hover-background: rgba(255, 255, 255, 0.08);
  --cb-vscode-descriptionForeground: var(--vscode-descriptionForeground, #9d9d9d);
  --cb-vscode-widget-border: var(--vscode-widget-border, #414141);
  --cb-vscode-panel-border: var(--vscode-panel-border, #3c3c3c);
  --cb-vscode-list-hoverBackground: var(--vscode-list-hoverBackground, #2a2d2e);
  --cb-vscode-toolbar-hoverBackground: var(--vscode-toolbar-hoverBackground, #353535);
  --cb-vscode-button-background: var(--vscode-button-background, #0e639c);
  --cb-vscode-button-foreground: var(--vscode-button-foreground, #ffffff);
  --cb-vscode-button-hoverBackground: var(--vscode-button-hoverBackground, #1177bb);
  --cb-vscode-button-secondaryBackground: var(--vscode-button-secondaryBackground, #3a3d41);
  --cb-vscode-button-secondaryForeground: var(--vscode-button-secondaryForeground, #ffffff);
  --cb-vscode-button-secondaryHoverBackground: var(--vscode-button-secondaryHoverBackground, #45494e);
  --cb-vscode-scrollbarSlider-background: var(--vscode-scrollbarSlider-background, #797979);
  --cb-vscode-scrollbarSlider-hoverBackground: var(--vscode-scrollbarSlider-hoverBackground, #646464);
  --cb-vscode-textLink-foreground: var(--vscode-textLink-foreground, #3794ff);
  --cb-vscode-list-activeSelectionForeground: var(--vscode-list-activeSelectionForeground, #ffffff);
  --cb-vscode-list-inactiveForeground: var(--vscode-foreground, #c5c5c5);
  --cb-vscode-focusBorder: var(--vscode-focusBorder, #007fd4);
  --cb-vscode-list-inactiveSelectionBackground: var(--vscode-list-inactiveSelectionBackground);
  --cb-vscode-widget-shadow: var(--vscode-widget-shadow, rgba(0, 0, 0, 0.36));
  --cb-vscode-menu-foreground: var(--vscode-menu-foreground, #cccccc);
  --cb-vscode-menu-separatorBackground: var(--vscode-menu-separatorBackground, #454545);
  --cb-vscode-menu-border: var(--vscode-menu-border, #454545);
  --cb-vscode-quickInputList-focusBackground: var(--vscode-quickInputList-focusBackground, #04395e);
  /* ========== 文件树和列表辅助变量 ========== */
  --cb-icon-foreground: var(--cb-vscode-foreground, #cccccc);
  --cb-list-activeSelectionBackground: var(--cb-vscode-list-activeSelectionBackground, #094771);
  --cb-list-focusBackground: var(--cb-vscode-list-focusBackground, #062f4a);
  --cb-tree-indent-guides-stroke: var(--cb-vscode-tree-indentGuidesStroke, rgba(255, 255, 255, 0.1));
  --cb-focus-outline-color: var(--cb-vscode-focusBorder, #007fd4);
  /* sidebar/tree 中"填充式"叶子项（默认就有底色，不靠 hover）三档语义 */
  --cb-list-item-bg: #1E2127;
  --cb-list-item-hover-bg: #272C34;
  --cb-list-item-selected-bg: #343841;
  /* ========== 滚动条相关 ========== */
  --cb-scrollbar-thumb: var(--cb-vscode-scrollbarSlider-background, rgba(121, 121, 121, 0.4));
  --cb-scrollbar-thumb-hover: var(--cb-vscode-scrollbarSlider-hoverBackground, rgba(100, 100, 100, 0.7));
  /* ========== 列表项颜色（用于 model selector 等） ========== */
  --cb-list-item-foreground: #c5c5c5;
  --cb-list-item-selected-foreground: #ffffff;
  /* ========== 基础颜色系统 ========== */
  --cb-success-color: #28b894;
  --cb-project-invitation-button-background: rgb(22, 163, 74);
  --cb-project-invitation-button-hover-background: rgb(22, 163, 74);
  --cb-project-invitation-card-background: rgb(255, 255, 255);
  --cb-project-invitation-hero-gradient: linear-gradient(rgb(240, 253, 244) 0%, rgb(255, 255, 255) 100%);
  --cb-button-primary: #6c4dff;
  --cb-mermaid-toggle-active: var(--cb-vscode-button-background, #0e639c);
  --cb-text-primary: #d2d3e0;
  --cb-text-secondary: #858699;
  --cb-text-tertiary: #a0a0a0;
  --cb-text-muted: rgba(232, 236, 241, 0.7);
  --cb-text-highlight: #40a6ff;
  /* 灰阶禁用文本（credit-estimate / installed-plugins 等组件使用），
     dark 与 wb 设计稿 --wb-color-text-disabled 对齐 */
  --cb-text-disabled: rgba(255, 255, 255, 0.25);
  /* ========== 设计稿语义补齐（dark 主题覆盖；WorkBuddy 仍通过 cb-bridge.scss 桥接到 --wb-*） ========== */
  --cb-text-error-active: #f14c4c;
  --cb-text-link-hover: #7AB8E8;
  --cb-text-solid: #ffffff;
  --cb-bg-primary-hover: rgba(255, 255, 255, 0.08);
  --cb-bg-primary-active: rgba(255, 255, 255, 0.12);
  --cb-border-secondary: rgba(255, 255, 255, 0.10);
  --cb-shadow-popover: 0 4px 12px -4px rgba(0, 0, 0, 0.4), 0 3px 6px -8px rgba(0, 0, 0, 0.4);
  --cb-shadow-message-toolbar: 0px 4px 12px 0px rgba(0, 0, 0, 0.4), 0px 3px 6px 0px rgba(0, 0, 0, 0.4);
  --cb-border-drag-indicator: #4DA3E0;
  /* ========== 输入框相关 ========== */
  --cb-input-foreground: var(--cb-text-primary);
  --cb-input-background: var(--cb-vscode-input-background);
  --cb-input-border-color: color-mix(in srgb, #cccccc 12%, transparent);
  --cb-input-focus-border-color: color-mix(in srgb, #cccccc 30%, transparent);
  --cb-input-placeholder: var(--cb-text-secondary);
  --cb-input-button-foreground: #D2D3E0;
  --cb-input-button-background: #4C4F6B;
  --cb-panel-border-color: color-mix(in srgb, #cccccc 12%, transparent);
  /* 聊天输入区域外层容器 (content) */
  --cb-content-background: color-mix(in srgb, var(--vscode-foreground) 4%, transparent);
  --cb-content-border-color: rgba(255, 255, 255, 0.08);
  /* 主输入区域 (mainArea) - 用户真正打字的地方 */
  --cb-main-area-background: var(--cb-vscode-input-background);
  --cb-main-area-border-color: var(--cb-content-border-color);
  --cb-main-area-box-shadow: none;
  /* ========== 标记和标签 ========== */
  --cb-marker-foreground: var(--cb-text-highlight);
  --cb-marker-background: #34414b;
  --cb-tag-background: rgba(128, 128, 128, 0.2);
  --cb-tag-selected-background: rgba(100, 150, 255, 0.3);
  --cb-tag-selected-text: #ffffff;
  /* skill/file tag / pending-auth chip 芯片底色（与 fileTag/skillTag 暗色模式对齐） */
  --cb-tag-skill-background: rgba(255, 255, 255, 0.08);
  --cb-tag-skill-background-hover: rgba(255, 255, 255, 0.14);
  /* 用户消息气泡 / 历史回放中的 skill/file chip 只读态底色（弱化，与气泡融合） */
  --cb-tag-skill-file-background: rgba(255, 255, 255, 0.06);
  /* 企业 Agent 下发启停标签（issue #56271 §5.1）:
     required=品牌蓝(与 --cb-info 对齐)；optional=弱化灰(与 skill 芯片一致) */
  --cb-tag-required-color: #2b5cff;
  --cb-tag-required-background: rgba(43, 92, 255, 0.16);
  --cb-tag-optional-color: rgba(255, 255, 255, 0.6);
  --cb-tag-optional-background: rgba(255, 255, 255, 0.08);
  /* ========== 弹出层相关 ========== */
  --cb-popover-background: #212234;
  --cb-popover-active-background: #313248;
  --cb-popover-secondary: var(--cb-text-secondary);
  --cb-popover-border: rgba(255, 255, 255, 0.12);
  --cb-popover-divider: rgba(255, 255, 255, 0.08);
  --cb-green-color: #00b96b;
  --cb-input-active-border: var(--cb-green-color);
  --cb-search-input-bg: rgba(255, 255, 255, 0.04);
  --cb-list-item-selected-bg: rgba(255, 255, 255, 0.06);
  --cb-toggle-track-off-bg: rgba(255, 255, 255, 0.08);
  --cb-switch-thumb-bg: #ffffff;
  --cb-avatar-fallback-bg: #3a3a3a;
  --cb-avatar-fallback-fg: rgba(255, 255, 255, 0.65);
  --cb-voice-pill-bg: rgba(255, 255, 255, 0.06);
  --cb-voice-text: rgba(255, 255, 255, 0.65);
  --cb-voice-confirm-color: #00c29a;
  --cb-voice-mic-hover-bg: rgba(255, 255, 255, 0.08);
  /* ========== 按钮相关变量 ========== */
  --cb-gray-color: color-mix(in srgb, var(--cb-vscode-foreground) 10%, transparent);
  --cb-mode-switch-background: var(--cb-gray-color);
  --cb-mode-switch-hover-background: rgba(255, 255, 255, 0.1);
  --cb-icon-button-hover-background: rgba(255, 255, 255, 0.1);
  --cb-icon-button-color: rgba(255, 255, 255, 0.2);
  --cb-send-button-loading-bg: rgba(255, 255, 255, 0.9);
  --cb-send-button-loading-color: rgba(0, 0, 0, 0.9);
  --cb-button-primary-foreground: #fff;
  --cb-danger-color: #d32f2f;
  --cb-button-ghost-hover-background: var(--cb-vscode-list-hoverBackground);
  /* 深色模式下反转为亮色按钮，确保与深色背景（#1e1e1e）有足够对比度 */
  --cb-button-dark-background: #ffffff;
  --cb-button-dark-foreground: #1a1a1a;
  --cb-button-dark-hover-background: #e0e0e0;
  /* ========== Input 相关变量 ========== */
  --chat-input-area-header-font-color: #CCC;
  --chat-input-add-btn-hover-bg-color: rgba(255, 255, 255, 0.1);
  --cb-chat-menu-main-text: #fff;
  /* ========== Switch 相关变量 ========== */
  --cb-switch-bg: #3a3a3a;
  --cb-switch-active-bg: #00b96b;
  --cb-switch-thumb-light-active: #f59e0b;
  --cb-switch-thumb-dark-active: #6366f1;
  --cb-switch-icon-light-active-color: #d2d3e0;
  --cb-switch-icon-dark-active-color: #d2d3e0;
  /* ========== 错误消息相关变量 ========== */
  --cb-error-foreground: #f14c4c;
  --cb-input-border-primary: #454545;
  /* ========== Tooltip 相关变量 ========== */
  --cb-dropdown-bg-color: var(--cb-vscode-dropdown-background);
  --cb-dropdown-item-hover-bg-color: var(--cb-vscode-list-hoverBackground);
  --cb-dropdown-border-color: rgba(255, 255, 255, 0.10);
  --cb-dropdown-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.32), 0 3px 6px -8px rgba(0, 0, 0, 0.32);
  --cb-tooltip-text-color: #FFFFFF;
  --cb-tooltip-shadow-color: rgba(0, 0, 0, 0.4);
  --cb-tooltip-bg: #333333;
  /* ========== 用户消息气泡 ========== */
  --cb-user-bubble-bg: #242424;
  /* ========== 基础交互变量 ========== */
  --cb-bg-primary: #101114;
  --cb-bg-secondary: #17191D;
  --cb-team-member-card-background: #23262D;
  --cb-team-member-icon-background: #23262D;
  --cb-search-bg: rgba(255, 255, 255, 0.04);
  --cb-bg-tertiary: #1E2127;
  --cb-bg-elevated: #181B20;
  --cb-bg-surface: #181B20;
  --cb-bg-surface-hover: #20242B;
  --cb-bg-surface-active: #272C34;
  --cb-bg-overlay: rgba(16, 17, 20, 0.9);
  --cb-hover-bg: #23262D;
  --cb-secondary-bg: #2d2d2d;
  --cb-sidebar-bg: #252526;
  --cb-sidebar-surface: rgba(255, 255, 255, 0.04);
  --cb-sidebar-surface-hover: rgba(255, 255, 255, 0.06);
  --cb-sidebar-active: rgba(255, 255, 255, 0.10);
  --cb-sidebar-search-bg: #181B20;
  --cb-border: rgba(255, 255, 255, 0.10);
  --cb-border-subtle: rgba(255, 255, 255, 0.06);
  --cb-border-strong: rgba(255, 255, 255, 0.16);
  --cb-border-bright: rgba(255, 255, 255, 0.16);
  --cb-text-primary-strong: rgba(255, 255, 255, 0.92);
  --cb-text-secondary-strong: rgba(255, 255, 255, 0.72);
  --cb-text-tertiary-strong: rgba(255, 255, 255, 0.48);
  --cb-text-quaternary: rgba(255, 255, 255, 0.32);
  --cb-sidebar-text: rgba(255, 255, 255, 0.90);
  --cb-sidebar-text-secondary: rgba(255, 255, 255, 0.66);
  --cb-sidebar-text-muted: rgba(255, 255, 255, 0.42);
  --cb-accent: #343841;
  --cb-accent-hover: #3E434E;
  --cb-bg-card: #181B20;
  /* ========== Markdown 相关变量 ========== */
  --cb-markdown-border-color: #3c3c3c;
  --cb-markdown-code-bg-color: rgba(255, 255, 255, 0.1);
  /* Markdown <hr> 边框色，与 wb 设计稿 --wb-color-border-secondary 对齐 */
  --cb-markdown-hr-border-color: #2A2C31;
  --cb-markdown-hljs-color: var(--cb-vscode-editor-foreground);
  --cb-markdown-symbol-color: #75beff;
  --cb-markdown-symbol-background: rgba(81, 154, 186, 0.15);
  --cb-markdown-symbol-hover-background: rgba(112, 174, 255, 0.25);
  /* Markdown 表格专用 token（与 light 主题对齐，独立于 markdown-border-color 避免影响 katex）。
     dark 下表头底色用 vscode editorWidget background；cell 背景用 transparent 继承容器，避免暗色出现刺眼白块。 */
  --cb-markdown-table-border-color: var(--cb-markdown-border-color, #3c3c3c);
  --cb-markdown-table-header-bg: var(--cb-vscode-editorWidget-background, #252526);
  --cb-markdown-table-cell-bg: transparent;
  /* Markdown 代码块专用 token（与 light 主题对齐）。
     dark 下不强制白底：边框沿用 markdown-border-color，header 用 editorWidget background，
     代码区背景 transparent 继承容器（避免暗色刺眼白块），文字色走 vscode foreground。 */
  --cb-markdown-code-block-border: var(--cb-markdown-border-color, #3c3c3c);
  --cb-markdown-code-block-header-bg: var(--cb-vscode-editorWidget-background, #252526);
  --cb-markdown-code-block-bg: transparent;
  --cb-markdown-code-block-title-fg: var(--cb-vscode-editor-foreground, #cccccc);
  --cb-markdown-code-block-action-fg: var(--cb-vscode-editor-foreground, #cccccc);
  --cb-markdown-code-block-action-hover-bg: rgba(255, 255, 255, 0.08);
  /* ========== Reasoning 内容变量 ========== */
  --cb-reasoning-bg: rgba(255, 255, 255, 0.05);
  --cb-reasoning-border-color: #3c3c3c;
  --cb-reasoning-font-color: #bbb;
  /* ========== 状态指示器颜色 ========== */
  --cb-integration-status-disconnected: #888;
