  --cb-question-floating-text-primary: rgba(255, 255, 255, 0.9);
  --cb-question-floating-text-secondary: rgba(255, 255, 255, 0.65);
  --cb-question-floating-text-muted: rgba(255, 255, 255, 0.4);
