  --cb-vscode-toolbar-hoverBackground: var(--vscode-toolbar-hoverBackground, #f0f0f0);
  --cb-vscode-button-background: var(--vscode-button-background, #007acc);
  --cb-vscode-button-foreground: var(--vscode-button-foreground, #ffffff);
  --cb-vscode-button-hoverBackground: var(--vscode-button-hoverBackground, #0062a3);
  --cb-vscode-button-secondaryBackground: var(--vscode-button-secondaryBackground, #5f6a79);
  --cb-vscode-button-secondaryForeground: var(--vscode-button-secondaryForeground, #ffffff);
  --cb-vscode-button-secondaryHoverBackground: var(--vscode-button-secondaryHoverBackground, #4c5561);
  --cb-vscode-scrollbarSlider-background: var(--vscode-scrollbarSlider-background, #c1c1c1);
  --cb-vscode-scrollbarSlider-hoverBackground: var(--vscode-scrollbarSlider-hoverBackground, #a8a8a8);
  --cb-vscode-textLink-foreground: var(--vscode-textLink-foreground, #006ab1);
  --cb-vscode-list-activeSelectionForeground: var(--vscode-list-activeSelectionForeground, #333333);
  --cb-vscode-list-inactiveForeground: var(--vscode-foreground, #616161);
  --cb-vscode-list-inactiveSelectionBackground: var(--vscode-list-inactiveSelectionBackground);
  --cb-vscode-widget-shadow: var(--vscode-widget-shadow, rgba(0, 0, 0, 0.16));
  --cb-vscode-menu-foreground: var(--vscode-menu-foreground, #333333);
  --cb-vscode-menu-separatorBackground: var(--vscode-menu-separatorBackground, #d4d4d4);
  --cb-vscode-menu-border: var(--vscode-menu-border, #d4d4d4);
  --cb-vscode-quickInputList-focusBackground: var(--vscode-quickInputList-focusBackground, #e8e8e8);
  /* ========== 文件树和列表辅助变量 ========== */
