/* ── 面板容器 ── */
.cr-permission-panel {
  width: 200px;
  padding: 8px;
  border-radius: 16px;
  background: var(--cr-bg-elevated);
  border: 0.5px solid var(--cr-border-default);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08), 0 1px 4px rgba(0, 0, 0, 0.04);
  box-sizing: border-box;
  user-select: none;
  outline: none !important;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cr-permission-panel:focus, .cr-permission-panel:focus-visible {
  outline: none !important;
}

.cr-permission-panel__desc {
  padding: 4px 8px;
  font-size: 12px;
  line-height: 20px;
  color: var(--cr-text-tertiary);
  white-space: pre-line;
}

.cr-permission-panel__divider {
  height: 1px;
  background: var(--cr-border-default);
  margin: 0;
}

.cr-permission-panel__group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cr-permission-panel__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 32px;
  padding: 0 8px;
  border-radius: 8px;
  cursor: pointer;
  box-sizing: border-box;
  gap: 8px;
}
.cr-permission-panel__row:hover {
  background: var(--cr-bg-hover);
}

.cr-permission-panel__row--disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.cr-permission-panel__row--disabled:hover {
  background: transparent;
}

.cr-permission-panel__row-label {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 14px;
  line-height: 22px;
  color: var(--cr-text-primary);
}

/* ── 26x16 开关 ── */
.cr-permission-toggle {
  flex: 0 0 26px;
  width: 26px;
  height: 16px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: var(--cr-toggle-off-bg);
  position: relative;
  cursor: pointer;
  transition: background-color 0.15s ease;
  outline: none;
}
.cr-permission-toggle:focus, .cr-permission-toggle:focus-visible {
  outline: none;
}

.cr-permission-toggle--on {
  background: var(--cr-permission-danger);
}

.cr-permission-toggle--disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.cr-permission-toggle__thumb {
  position: absolute;
  top: 2px;
  left: 2px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.15s ease;
}

.cr-permission-toggle--on .cr-permission-toggle__thumb {
  transform: translateX(10px);
}

/* ── 二次确认弹窗 ── */
.cr-permission-confirm-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(0, 0, 0, 0.4);
}

.cr-permission-confirm {
  width: 480px;
  max-width: calc(100vw - 32px);
  border-radius: 24px;
  padding: 24px;
  background: var(--cr-bg-elevated);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.cr-permission-confirm__title {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 16px;
  line-height: 24px;
  color: var(--cr-text-primary);
  font-weight: 600;
}

.cr-permission-confirm__desc {
  padding-left: 28px;
  font-size: 14px;
  line-height: 22px;
  color: var(--cr-text-secondary);
  white-space: pre-line;
  margin: 0;
}

.cr-permission-confirm__checkbox {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding-left: 28px;
  cursor: pointer;
  font-size: 14px;
  line-height: 22px;
  color: var(--cr-text-secondary);
  user-select: none;
}
.cr-permission-confirm__checkbox input[type=checkbox] {
  appearance: none;
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  margin: 0;
  padding: 0;
  flex: 0 0 16px;
  border: none;
  border-radius: 0;
  background: transparent;
  cursor: pointer;
  position: relative;
}
.cr-permission-confirm__checkbox input[type=checkbox]::before {
  content: "";
  position: absolute;
  top: 1px;
  left: 1px;
  width: 14px;
  height: 14px;
  border: 1px solid var(--cr-border-default);
  border-radius: 0;
  background: var(--cr-bg-elevated);
  box-sizing: border-box;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
.cr-permission-confirm__checkbox input[type=checkbox]:checked::before {
  background: var(--cr-accent);
  border-color: var(--cr-accent);
}
.cr-permission-confirm__checkbox input[type=checkbox]:checked::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 6px;
  width: 4px;
  height: 8px;
  border: solid #fff;
  border-width: 0 1.5px 1.5px 0;
  transform: rotate(45deg);
}
.cr-permission-confirm__checkbox input[type=checkbox]:focus, .cr-permission-confirm__checkbox input[type=checkbox]:focus-visible {
  outline: none;
}

.cr-permission-confirm__actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  padding-top: 8px;
}

.cr-permission-confirm__btn-cancel {
  height: 36px;
  padding: 0 20px;
  border-radius: 8px;
  border: 1px solid var(--cr-border-default);
  background: transparent;
  color: var(--cr-text-primary);
  font-size: 14px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.cr-permission-confirm__btn-cancel:hover {
  background: var(--cr-bg-hover);
}

.cr-permission-confirm__btn-danger {
  height: 36px;
  padding: 0 20px;
  border-radius: 8px;
  border: none;
  background: #F64041;
  color: #fff;
  font-size: 14px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.cr-permission-confirm__btn-danger:hover {
  background: #e03030;
}

.cr-permission-confirm__btn-danger--disabled {
  background: #F5B9B9;
  cursor: not-allowed;
}
.cr-permission-confirm__btn-danger--disabled:hover {
  background: #F5B9B9;
}
