  background: transparent;
  color: var(--cr-text-tertiary);
  font-size: 14px;
  line-height: 1;
  cursor: pointer;
  flex-shrink: 0;
  transition: background 0.1s, color 0.1s;
}
.cr-input-notification-banner__close:hover {
