  bottom: 100%;
  left: 0;
  right: 0;
  margin-bottom: -32px;
  max-height: 296px;
  overflow: hidden;
  overscroll-behavior: none;
  border-radius: 24px 24px 0 0;
  border: 1px solid var(--cr-border-default, #dedede);
  border-bottom: none;
  background: var(--cr-bg-elevated, #fff);
  box-shadow: 0 6px 24px 0 rgba(0, 0, 0, 0.04), 0 4px 6px 0 rgba(0, 0, 0, 0.04);
  z-index: 1;
  display: flex;
  flex-direction: column;
  padding-top: 8px;
  box-sizing: border-box;
}

.cr-trigger-search-panel__scroll {
  position: static;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  overscroll-behavior: none;
  padding: 0 8px 40px;
}
.cr-trigger-search-panel__scroll::-webkit-scrollbar {
  width: 6px;
}
.cr-trigger-search-panel__scroll::-webkit-scrollbar-track {
  background: transparent;
  margin-top: 28px;
  margin-bottom: 40px;
}
.cr-trigger-search-panel__scroll::-webkit-scrollbar-thumb {
  background-color: var(--cr-scrollbar-thumb, #ebebeb);
  background-clip: padding-box;
  border-right: 2px solid transparent;
  border-radius: 3px;
}

.cr-trigger-search-panel__empty,
.cr-trigger-search-panel__loading {
  padding: 12px 16px;
