  font-size: 14px;
  line-height: 22px;
  color: var(--cr-text-tertiary, rgba(0, 0, 0, 0.3));
}

.cr-trigger-search-panel__group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: var(--cr-bg-elevated, #fff);
}

.cr-trigger-search-panel__group-title {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 4px;
  box-sizing: border-box;
  height: 28px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
