  color: rgba(0, 0, 0, 0.5);
  background: var(--cr-bg-elevated, #fff);
  user-select: none;
  cursor: default;
}

.cr-trigger-search-panel__group:first-of-type:not(:last-of-type) {
  border-bottom: 1px solid #f2f2f2;
  margin-bottom: 8px;
}

.cr-trigger-search-panel__group-title-label,
.cr-trigger-search-panel__group-title-count {
  font-weight: inherit;
}

.cr-trigger-search-panel__group:not(:first-of-type) > .cr-trigger-search-panel__group-title {
  height: 32px;
  padding: 6px 8px;
  top: 28px;
}

.cr-trigger-search-panel__accordion-top,
.cr-trigger-search-panel__accordion-bottom {
  position: absolute;
  left: 8px;
  right: 8px;
  display: flex;
  align-items: center;
  gap: 4px;
  height: 28px;
  padding: 4px 8px;
  font-size: 12px;
  font-weight: 600;
  line-height: 20px;
  color: rgba(0, 0, 0, 0.5);
  background: var(--cr-bg-elevated, #fff);
  z-index: 3;
  cursor: default;
  user-select: none;
  pointer-events: auto;
  box-sizing: border-box;
}

.cr-trigger-search-panel__accordion-top {
  top: 8px;
  border-bottom: 1px solid #f2f2f2;
}

.cr-trigger-search-panel__accordion-bottom {
  height: 32px;
  padding: 6px 8px;
  bottom: 32px;
  border-top: 1px solid #f2f2f2;
}

.cr-trigger-search-panel__item {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 32px;
  padding: 0 8px;
  cursor: pointer;
  user-select: none;
  font-size: 14px;
  line-height: 22px;
  color: var(--cr-text-primary, rgba(0, 0, 0, 0.9));
  transition: background 0.1s;
  border-radius: 8px;
}
.cr-trigger-search-panel__item:hover, .cr-trigger-search-panel__item--selected {
  background: var(--cr-bg-hover, #f2f2f2);
}
.cr-trigger-search-panel__item--disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.cr-trigger-search-panel__item-icon {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
