  min-width: 0;
  font-size: 12px;
  font-weight: 400;
  line-height: 22px;
  color: var(--cr-text-secondary, rgba(0, 0, 0, 0.6));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cr-trigger-search-panel__item-desc mark {
  background: transparent;
  color: var(--cr-brand-primary, #00b96b);
  font-weight: inherit;
}

.cr-trigger-search-panel__item-right {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: auto;
}
/**
 * _cr.scss —— SCSS 类名前缀 helper
 *
 * 目的：写组件样式时无需重复敲 `cr-` 前缀，sass 编译时自动补上。
