  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}
.cr-resize-handle {
  height: 4px;
  cursor: ns-resize;
  user-select: none;
  flex-shrink: 0;
  position: absolute;
  top: -5px;
  left: 8px;
  right: 8px;
  z-index: 10;
}
.cr-resize-handle::before {
  content: "";
  position: absolute;
  top: -4px;
  left: -8px;
  right: -8px;
  bottom: -4px;
  pointer-events: none;
}
.cr-resize-handle--disabled {
  cursor: not-allowed;
  opacity: 0.5;
  pointer-events: none;
}
.cr-resize-handle--bottom {
  top: auto;
  bottom: -5px;
}

:global(body.cr-resizing) {
  cursor: ns-resize !important;
  user-select: none !important;
}
:global(body.cr-resizing) * {
  cursor: ns-resize !important;
}
