.cr-workspace-picker-popover {
  width: 240px;
  display: flex;
  flex-direction: column;
  max-height: 376px;
  animation: workspacePopIn 0.18s ease-out both;
  background: var(--cr-bg-elevated);
  border-radius: 16px;
}

@keyframes workspacePopIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
/* 搜索框（复用 SearchInput 组件） */
.cr-workspace-picker-popover__search {
  padding: 8px 8px 4px;
}

/* 列表 */
.cr-workspace-picker-popover__list {
  flex: 1;
  overflow-y: auto;
  padding: 4px;
}

.cr-workspace-picker-popover__empty {
  padding: 16px 12px;
  text-align: center;
  font-size: 13px;
  color: var(--cr-text-tertiary);
}

.cr-workspace-picker-popover__item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.15s ease;
}
.cr-workspace-picker-popover__item:hover {
  background: var(--cr-bg-hover);
}

.cr-workspace-picker-popover__item--selected {
  background: var(--cr-bg-hover);
}

.cr-workspace-picker-popover__item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  color: var(--cr-text-secondary);
}

.cr-workspace-picker-popover__item-label {
  flex: 1;
  min-width: 0;
  font-size: 13px;
  line-height: 20px;
  color: var(--cr-text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.cr-workspace-picker-popover__item-check {
  flex: 0 0 16px;
  width: 16px;
  height: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* 搜索高亮 */
.cr-workspace-picker-popover__highlight {
  color: var(--cr-brand-primary);
  background: transparent;
}

/* 分隔线 */
.cr-workspace-picker-popover__divider {
  height: 1px;
  background: var(--cr-border-default);
  margin: 4px 0;
}

/* footer */
.cr-workspace-picker-popover__footer {
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  padding: 4px;
  /* footer slot 内的子元素（如「新建工作空间」）统一加 hover 态 */
}
