  border-radius: 6px;
  transition: background-color 0.15s ease;
}
.cr-workspace-picker-popover__footer > *:hover {
  background: var(--cr-bg-hover);
}

.cr-workspace-picker-popover__bottom {
  flex: 0 0 auto;
}
