.cr-input-footer-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  padding: 0 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--cr-text-tertiary, rgba(0, 0, 0, 0.5));
  cursor: pointer;
  flex-shrink: 0;
  font-family: "PingFang SC", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  transition: color 0.15s ease, font-weight 0.15s ease;
}
.cr-input-footer-item:hover:not(:disabled) {
  color: var(--cr-text-primary, rgba(0, 0, 0, 0.9));
}
.cr-input-footer-item:hover:not(:disabled) .cr-input-footer-item__label {
  font-weight: 500;
}
.cr-input-footer-item:focus-visible {
  outline: 2px solid var(--cb-focus-border, #007fd4);
  outline-offset: 2px;
}

.cr-input-footer-item__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: inherit;
  flex-shrink: 0;
}

.cr-input-footer-item__label {
  font-size: 13px;
  font-weight: normal;
  line-height: 20px;
  white-space: nowrap;
  user-select: none;
  transition: font-weight 0.15s ease;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 180px;
}

.cr-input-footer-item__chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  color: inherit;
  flex-shrink: 0;
  transition: transform 0.42s cubic-bezier(0.25, 0.8, 0.3, 1);
  transform-origin: center;
}
/**
 * QuickActionBar 样式
 *
 * 设计稿参考：节点 14243:1790
 * - 容器：水平 flex wrap，itemSpacing: 8
 * - 每个 chip：height 32px, borderRadius 8, paddingLR 12, 1px solid #e5e5e5
 * - 图标 16×16, 文字 13px/22px Medium, 颜色 rgba(0,0,0,0.7)
 * - 选中态：bg #f2f2f2, 无可见 border
 */
.cr-quick-action-bar {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.cr-quick-action-bar__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.cr-quick-action-bar__chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--cr-border-default);
  border-radius: 8px;
  background: transparent;
  color: var(--cr-text-secondary);
  font-size: 13px;
  font-weight: 500;
  line-height: 22px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}
.cr-quick-action-bar__chip:hover {
  background: var(--cr-bg-hover);
}
.cr-quick-action-bar__chip--active {
  height: 36px;
  background: var(--cr-bg-input-inset);
  border-color: transparent;
}
.cr-quick-action-bar__chip-icon {
  display: inline-flex;
  align-items: center;
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}
.cr-quick-action-bar__chip-icon > svg,
.cr-quick-action-bar__chip-icon > img {
  width: 16px;
  height: 16px;
}
.cr-quick-action-bar__chip-arrow {
  display: inline-flex;
  font-size: 12px;
  transform: rotate(90deg);
  transition: transform 0.15s ease;
}
.cr-quick-action-bar__chip-arrow--up {
  transform: rotate(-90deg);
}
.cr-quick-action-bar__options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.cr-quick-action-bar__option {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 32px;
  padding: 0 12px;
  border: 1px solid var(--cr-border-default);
  border-radius: 8px;
  background: transparent;
  color: var(--cr-text-secondary);
  font-size: 13px;
  font-weight: 500;
  line-height: 22px;
  cursor: pointer;
  transition: background 0.15s ease;
  white-space: nowrap;
}
.cr-quick-action-bar__option:hover {
  background: var(--cr-bg-hover);
}
.cr-quick-action-bar__option-arrow {
  font-size: 11px;
  color: var(--cr-text-tertiary);
}
