.cr-conversation-event {
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 240px;
  box-sizing: border-box;
  padding: 12px 0;
  color: var(--cr-text-secondary, #999);
  user-select: none;
}

.cr-conversation-event__line {
  flex: 1;
  min-width: 24px;
  height: 1px;
  background: var(--cr-border-default, #e0e0e0);
}

.cr-conversation-event--line-dashed .cr-conversation-event__line {
  background: linear-gradient(90deg, var(--cr-text-secondary, #999) 8px, transparent 8px);
  background-size: 16px 1px;
  background-repeat: repeat-x;
}

.cr-conversation-event__content {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: min(720px, 100vw - 80px);
  margin: 0 8px;
  white-space: nowrap;
}

.cr-conversation-event__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  flex: none;
  color: var(--cr-text-secondary, #999);
}

.cr-conversation-event__title {
  overflow: hidden;
  text-overflow: ellipsis;
  color: currentColor;
  font-size: 12px;
  line-height: 18px;
}

.cr-conversation-event__info {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 13px;
  height: 13px;
  flex: none;
  border: 1px solid currentColor;
  border-radius: 50%;
  color: var(--cr-text-tertiary);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  cursor: default;
}

.cr-conversation-event__action {
  appearance: none;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--cr-text-link, #0066cc);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  line-height: 18px;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.cr-conversation-event__action:hover {
  color: var(--cr-text-link-hover, var(--cr-text-link, #0066cc));
}

.cr-conversation-event__tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  z-index: 100;
  width: max-content;
  max-width: 260px;
  box-sizing: border-box;
  padding: 8px 12px;
  transform: translateX(-50%);
  border: 1px solid var(--cr-border-default);
  border-radius: 8px;
  background: var(--cr-bg-primary);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--cr-text-primary) 14%, transparent);
  color: var(--cr-text-primary);
  font-size: 12px;
  font-weight: 500;
  line-height: 18px;
  pointer-events: none;
  text-align: center;
  white-space: pre-line;
}

.cr-conversation-event--running .cr-conversation-event__title {
  background: linear-gradient(90deg, var(--cr-text-secondary, #999) 25%, var(--cr-bg-primary, #fff) 50%, var(--cr-text-secondary, #999) 75%);
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: cr-conversation-event-shimmer 1.8s linear infinite;
}

.cr-conversation-event--success {
  color: var(--cr-text-secondary, #999);
}

.cr-conversation-event--cancelled {
  color: var(--cr-text-secondary, #999);
}
.cr-conversation-event--cancelled .cr-conversation-event__title {
  opacity: 0.75;
  text-decoration: line-through;
  text-decoration-color: var(--cr-text-secondary, #999);
  text-decoration-style: solid;
}
.cr-conversation-event--cancelled .cr-conversation-event__icon {
  opacity: 0.75;
}

.cr-conversation-event--warning {
  color: var(--cr-text-secondary, #999);
}
.cr-conversation-event--warning .cr-conversation-event__title {
  color: var(--cr-status-warning, #e6a700);
}

@keyframes cr-conversation-event-shimmer {
  0% {
    background-position: 200% center;
  }
  100% {
    background-position: -200% center;
  }
}
/**
