  width: 100%;
  border: 1px solid var(--cr-border-default);
  border-radius: 16px;
  overflow: hidden;
  background: var(--cr-bg-primary);
  margin: 8px 0;
}

.cr-widget-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 6px 8px 6px 16px;
  border-bottom: 1px solid var(--cr-border-default);
  background: var(--cr-bg-secondary);
}

.cr-widget-header-title {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  line-height: 20px;
  color: var(--cr-text-primary);
  min-width: 0;
}

.cr-widget-header-check {
  display: inline-flex;
  flex: none;
  color: inherit;
}
.cr-widget-header-check svg {
  width: 16px;
  height: 16px;
}

.cr-widget-body {
  position: relative;
  width: 100%;
  padding: 12px 16px;
}

.cr-widget-iframe {
  display: block;
  width: 100%;
  border: none;
  min-height: 60px;
  background: transparent;
}
.cr-widget-iframe--hidden {
  display: none;
}

.cr-widget-header-actions {
  position: relative;
  flex: none;
}

.cr-widget-actions-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  color: var(--cr-text-secondary);
  background: transparent;
  transition: background-color 0.15s ease, color 0.15s ease;
}
.cr-widget-actions-button:hover {
  color: var(--cr-text-primary);
  background: var(--cr-bg-hover);
}
.cr-widget-actions-button:focus, .cr-widget-actions-button:focus-visible {
  outline: none;
}
.cr-widget-actions-button svg {
  width: 16px;
  height: 16px;
}

.cr-widget-menu {
  position: absolute;
  top: calc(100% + 4px);
  right: 0;
  z-index: 3;
  min-width: 136px;
  padding: 4px;
  border: 1px solid var(--cr-border-default);
  border-radius: 10px;
  background: var(--cr-bg-primary);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--cr-text-primary) 16%, transparent);
}

.cr-widget-menu-item {
  display: block;
  width: 100%;
  padding: 7px 12px;
  border: none;
  border-radius: 6px;
  font-size: 13px;
  line-height: 20px;
  text-align: left;
  white-space: nowrap;
  cursor: pointer;
  color: var(--cr-text-primary);
  background: transparent;
}
.cr-widget-menu-item:hover:not(:disabled) {
  background: var(--cr-bg-hover);
}
.cr-widget-menu-item:disabled {
  color: var(--cr-text-disabled);
  cursor: not-allowed;
}

.cr-widget-bootstrap-pending {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  opacity: 0.7;
  pointer-events: none;
}

.cr-widget-bootstrap-pending-text {
  line-height: 1.4;
}

.cr-widget-loading-line {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 12px;
  opacity: 0.7;
}

.cr-widget-loading-spinner {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid currentColor;
